from typing import Any, Optional

from flet.core.constrained_control import ConstrainedControl, OptionalNumber
from flet.core.control_event import ControlEvent
from flet.core.event_handler import EventHandler
from flet.core.ref import Ref
from flet.core.types import OptionalEventCallable


class BarcodeDetectEvent(ControlEvent):
    def __init__(self, e: ControlEvent):
        super().__init__(e.target, e.name, e.data, e.control, e.page)
        self.code: str = e.data


class BarcodeScanner(ConstrainedControl):
    """
    A control that shows a live camera preview and decodes barcodes/QR
    codes from it, backed by the Flutter `mobile_scanner` plugin (AVFoundation
    on iOS, ML Kit on Android) -- replaces OpenCV's
    cv2.barcode.BarcodeDetector/cv2.QRCodeDetector, which cannot ship on iOS.

    Fires on_detect exactly once per start()/stop() session: the Dart side
    stops emitting further detections after the first hit, matching the old
    CameraEngine.stream_views' "freeze on first hit" behavior.
    """

    def __init__(
        self,
        on_detect: OptionalEventCallable[BarcodeDetectEvent] = None,
        on_error: OptionalEventCallable = None,
        #
        # ConstrainedControl
        #
        ref: Optional[Ref] = None,
        width: OptionalNumber = None,
        height: OptionalNumber = None,
        expand: Any = None,
        visible: Optional[bool] = None,
        data: Any = None,
    ):
        ConstrainedControl.__init__(
            self,
            ref=ref,
            width=width,
            height=height,
            expand=expand,
            visible=visible,
            data=data,
        )
        self.__on_detect = EventHandler(lambda e: BarcodeDetectEvent(e))
        self._add_event_handler("detect", self.__on_detect.get_handler())
        self.__on_error = EventHandler(lambda e: e)
        self._add_event_handler("error", self.__on_error.get_handler())

        self.on_detect = on_detect
        self.on_error = on_error

    def _get_control_name(self):
        return "barcode_scanner"

    def start(self, wait_timeout: Optional[float] = 10) -> bool:
        started = self.invoke_method(
            "start", wait_for_result=True, wait_timeout=wait_timeout
        )
        return started == "true"

    async def start_async(self, wait_timeout: Optional[float] = 10) -> bool:
        started = await self.invoke_method_async(
            "start", wait_for_result=True, wait_timeout=wait_timeout
        )
        return started == "true"

    def stop(self, wait_timeout: Optional[float] = 5) -> None:
        self.invoke_method("stop", wait_for_result=True, wait_timeout=wait_timeout)

    async def stop_async(self, wait_timeout: Optional[float] = 5) -> None:
        await self.invoke_method_async(
            "stop", wait_for_result=True, wait_timeout=wait_timeout
        )

    # on_detect
    @property
    def on_detect(self):
        return self.__on_detect.handler

    @on_detect.setter
    def on_detect(self, handler: OptionalEventCallable[BarcodeDetectEvent]):
        self.__on_detect.handler = handler

    # on_error
    @property
    def on_error(self):
        return self.__on_error.handler

    @on_error.setter
    def on_error(self, handler: OptionalEventCallable):
        self.__on_error.handler = handler
